39	impl FileResolver for FsResolver {
40	    fn read(&self, path: &str) -> Result<String, CoreError> {
41	        std::fs::read_to_string(self.base.join(path)).map_err(|error| CoreError {
42	            message: error.to_string(),
43	            line: 1,
44	            column: 1,
45	            origin: None,
46	            name_resolution: false,
47	        })
48	    }
49	}
