249	/// Lower one compose document using source-relative component resolution.
250	///
251	/// # Errors
252	///
253	/// Returns [`CoreError`] for missing/invalid components, unknown aliases or
254	/// actions, sync arity mismatches, and nested compose inputs.
255	#[allow(clippy::too_many_lines)]
256	pub fn lower_compose(
257	    compose: SurfaceCompose,
258	    resolver: &dyn FileResolver,
259	) -> Result<KernelSpec, CoreError> {
260	    let mut components = BTreeMap::new();
261	    let mut component_annotations = Annotations::default();
262	    let mut order = Vec::new();
263	    for item in &compose.items {
264	        let ComposeItem::Use {
265	            spec_name: _,
266	            alias,
267	            path,
268	            span,
269	        } = item
270	        else {
271	            continue;
272	        };
273	        if components.contains_key(alias) {
274	            return Err(error_at(format!("duplicate alias '{alias}'"), *span));
275	        }
276	        let source = resolver
277	            .read(path)
278	            .map_err(|error| component_error(path, *span, &error, "could not be read"))?;
279	        let (spec, annotations) = parse_component(&source, path, *span)?;
280	        component_annotations.extend(annotations.source_order().iter().cloned());
281	        order.push(alias.clone());
282	        components.insert(
283	            alias.clone(),
284	            Component {
285	                alias: alias.clone(),
286	                names: ComponentNames::collect(&spec),
287	                spec,
288	            },
289	        );
290	    }
291	    let internal = compose
292	        .items
293	        .iter()
294	        .filter_map(|item| match item {
295	            ComposeItem::Internal { alias, action, .. } => Some((alias.clone(), action.clone())),
296	            _ => None,
297	        })
298	        .collect::<HashSet<_>>();
299	
300	    let mut warnings = Vec::new();
301	    let mut static_items = Vec::new();
302	    let mut init = Vec::new();
303	    let mut init_meta = None;
304	    let mut init_annotations = Annotations::default();
305	    let mut actions = Vec::new();
306	    for alias in &order {
307	        let component = &components[alias];
308	        for item in &component.spec.items {
309	            match item {
310	                SpecItem::Init {
311	                    statements,
312	                    meta,
313	                    annotations,
314	                } => {
315	                    init.extend(rewrite_statements(
316	                        statements.clone(),
317	                        component,
318	                        &HashSet::new(),
319	                    ));
320	                    if init_meta.is_none() {
321	                        init_meta.clone_from(meta);
322	                    }
323	                    init_annotations.extend(annotations.source_order().iter().cloned());
324	                }
325	                SpecItem::Action { name, .. } => {
326	                    if !internal.contains(&(alias.clone(), name.clone())) {
327	                        actions.push(rewrite_component_item(item.clone(), component));
328	                    }
329	                }
330	                _ => static_items.push(rewrite_component_item(item.clone(), component)),
331	            }
332	        }
333	    }
334	
335	    for item in &compose.items {
336	        match item {
337	            ComposeItem::Common(SpecItem::State(fields)) => {
338	                static_items.push(SpecItem::State(fields.clone()));
339	            }
340	            ComposeItem::Common(SpecItem::Init {
341	                statements,
342	                meta,
343	                annotations,
344	            }) => {
345	                init.extend(rewrite_compose_statements(statements.clone(), &components));
346	                if init_meta.is_none() {
347	                    init_meta.clone_from(meta);
348	                }
349	                init_annotations.extend(annotations.source_order().iter().cloned());
350	            }
351	            ComposeItem::Common(item) => {
352	                static_items.push(rewrite_compose_item(item.clone(), &components)?);
353	            }
354	            ComposeItem::SyncAction(action) => {
355	                actions.push(sync_action(action, &components, &mut warnings)?);
356	            }
357	            ComposeItem::Use { .. } | ComposeItem::Internal { .. } => {}
358	        }
359	    }
360	    static_items.push(SpecItem::Init {
361	        statements: init,
362	        meta: init_meta,
363	        annotations: init_annotations,
364	    });
365	    static_items.extend(actions);
366	    Ok(composed_kernel(
367	        compose.name,
368	        static_items,
369	        component_annotations,
370	        warnings,
371	    ))
372	}
373	
374	fn prefix(alias: &str, name: &str) -> String {
375	    format!("{alias}__{name}")
376	}
377	
378	fn error_at(message: impl Into<String>, span: fsl_syntax::Span) -> CoreError {
379	    CoreError {
380	        message: message.into(),
381	        line: span.start.line,
382	        column: span.start.column,
383	        origin: None,
384	        name_resolution: false,
385	    }
386	}
