388	#[allow(clippy::too_many_lines)]
389	fn rewrite_component_item(item: SpecItem, component: &Component) -> SpecItem {
390	    let alias = &component.alias;
391	    match item {
392	        SpecItem::Const { name, value } => SpecItem::Const {
393	            name: prefix(alias, &name),
394	            value: Box::new(rewrite_expr(*value, component, &HashSet::new())),
395	        },
396	        SpecItem::Type {
397	            name,
398	            lo,
399	            hi,
400	            symmetric,
401	        } => SpecItem::Type {
402	            name: prefix(alias, &name),
403	            lo: Box::new(rewrite_expr(*lo, component, &HashSet::new())),
404	            hi: Box::new(rewrite_expr(*hi, component, &HashSet::new())),
405	            symmetric,
406	        },
407	        SpecItem::Enum {
408	            name,
409	            members,
410	            member_spans,
411	            symmetric,
412	        } => SpecItem::Enum {
413	            name: prefix(alias, &name),
414	            members,
415	            member_spans,
416	            symmetric,
417	        },
418	        SpecItem::Struct { name, fields, span } => SpecItem::Struct {
419	            name: prefix(alias, &name),
420	            span,
421	            fields: fields
422	                .into_iter()
423	                .map(|(name, ty)| (name, rewrite_type(ty, component)))
424	                .collect(),
425	        },
426	        SpecItem::State(fields) => SpecItem::State(
427	            fields
428	                .into_iter()
429	                .map(|field| fsl_syntax::StateField {
430	                    name: prefix(alias, &field.name),
431	                    ty: rewrite_type(field.ty, component),
432	                    initializer: field
433	                        .initializer
434	                        .map(|expr| rewrite_expr(expr, component, &HashSet::new())),
435	                    span: field.span,
436	                    initializer_span: field.initializer_span,
437	                })
438	                .collect(),
439	        ),
440	        SpecItem::Init {
441	            statements,
442	            meta,
443	            annotations,
444	        } => SpecItem::Init {
445	            statements: rewrite_statements(statements, component, &HashSet::new()),
446	            meta,
447	            annotations,
448	        },
449	        SpecItem::Action {
450	            name,
451	            params,
452	            items,
453	            span,
454	            fair,
455	            meta,
456	            sync,
457	            annotations,
458	        } => {
459	            let params = params
460	                .into_iter()
461	                .map(|param| rewrite_param(param, component))
462	                .collect::<Vec<_>>();
463	            let bound = params
464	                .iter()
465	                .map(|param| match param {
466	                    Param::Typed(name, _) | Param::Range(name, _, _) => name.clone(),
467	                })
468	                .collect();
469	            SpecItem::Action {
470	                name: prefix(alias, &name),
471	                params,
472	                items: rewrite_action_items(items, component, &bound),
473	                span,
474	                fair,
475	                meta,
476	                sync,
477	                annotations,
478	            }
479	        }
480	        SpecItem::Invariant {
481	            name,
482	            expr,
483	            span,
484	            meta,
485	            annotations,
486	        } => SpecItem::Invariant {
487	            name: prefix(alias, &name),
488	            expr: Box::new(rewrite_expr(*expr, component, &HashSet::new())),
489	            span,
490	            meta,
491	            annotations,
492	        },
493	        SpecItem::Trans {
494	            name,
495	            expr,
496	            span,
497	            meta,
498	            annotations,
499	        } => SpecItem::Trans {
500	            name: prefix(alias, &name),
501	            expr: Box::new(rewrite_expr(*expr, component, &HashSet::new())),
502	            span,
503	            meta,
504	            annotations,
505	        },
506	        SpecItem::Reachable {
507	            name,
508	            expr,
509	            span,
510	            meta,
511	            annotations,
512	        } => SpecItem::Reachable {
513	            name: prefix(alias, &name),
514	            expr: Box::new(rewrite_expr(*expr, component, &HashSet::new())),
515	            span,
516	            meta,
517	            annotations,
518	        },
519	        SpecItem::Terminal { expr, span } => SpecItem::Terminal {
520	            expr: Box::new(rewrite_expr(*expr, component, &HashSet::new())),
521	            span,
522	        },
523	        SpecItem::LeadsTo {
524	            name,
525	            binders,
526	            before,
527	            after,
528	            span,
529	            meta,
530	            decreases,
531	            within,
532	            helpful,
533	            annotations,
534	        } => {
535	            let mut bound = HashSet::new();
536	            let binders = binders
537	                .into_iter()
538	                .map(|binder| {
539	                    let binder = rewrite_binder(binder, component, &bound);
540	                    bound.insert(binder_name(&binder).to_owned());
541	                    binder
542	                })
543	                .collect();
544	            SpecItem::LeadsTo {
545	                name: prefix(alias, &name),
546	                binders,
547	                before: Box::new(rewrite_expr(*before, component, &bound)),
548	                after: Box::new(rewrite_expr(*after, component, &bound)),
549	                span,
550	                meta,
551	                decreases: decreases.map(|expr| Box::new(rewrite_expr(*expr, component, &bound))),
552	                within: within.map(|expr| Box::new(rewrite_expr(*expr, component, &bound))),
553	                helpful,
554	                annotations,
555	            }
556	        }
557	        item @ (SpecItem::Until { .. }
558	        | SpecItem::Unless { .. }
559	        | SpecItem::VerifyBounds { .. }
560	        | SpecItem::Entity(..)
561	        | SpecItem::Number(..)
562	        | SpecItem::Def { .. }) => item,
563	    }
564	}
