566	fn rewrite_type(ty: TypeExpr, component: &Component) -> TypeExpr {
567	    match ty {
568	        TypeExpr::Name(name) if component.names.types.contains(&name) => {
569	            TypeExpr::Name(prefix(&component.alias, &name))
570	        }
571	        TypeExpr::Range(lo, hi) => TypeExpr::Range(
572	            rewrite_expr(lo, component, &HashSet::new()),
573	            rewrite_expr(hi, component, &HashSet::new()),
574	        ),
575	        TypeExpr::Map(key, value) => TypeExpr::Map(
576	            Box::new(rewrite_type(*key, component)),
577	            Box::new(rewrite_type(*value, component)),
578	        ),
579	        TypeExpr::Relation(source, target) => TypeExpr::Relation(
580	            Box::new(rewrite_type(*source, component)),
581	            Box::new(rewrite_type(*target, component)),
582	        ),
583	        TypeExpr::Set(inner) => TypeExpr::Set(Box::new(rewrite_type(*inner, component))),
584	        TypeExpr::Seq(inner, cap) => TypeExpr::Seq(
585	            Box::new(rewrite_type(*inner, component)),
586	            rewrite_expr(cap, component, &HashSet::new()),
587	        ),
588	        TypeExpr::Option(inner) => TypeExpr::Option(Box::new(rewrite_type(*inner, component))),
589	        other => other,
590	    }
591	}
592	
593	fn rewrite_param(param: Param, component: &Component) -> Param {
594	    match param {
595	        Param::Typed(name, mut qualified) => {
596	            if qualified.namespace.is_none() && component.names.types.contains(&qualified.name) {
597	                qualified.name = prefix(&component.alias, &qualified.name);
598	            }
599	            Param::Typed(name, qualified)
600	        }
601	        Param::Range(name, lo, hi) => Param::Range(
602	            name,
603	            rewrite_expr(lo, component, &HashSet::new()),
604	            rewrite_expr(hi, component, &HashSet::new()),
605	        ),
606	    }
607	}
608	
609	fn rewrite_action_items(
610	    items: Vec<ActionItem>,
611	    component: &Component,
612	    bound: &HashSet<String>,
613	) -> Vec<ActionItem> {
614	    items
615	        .into_iter()
616	        .map(|item| match item {
617	            ActionItem::Requires(expr, span) => {
618	                ActionItem::Requires(rewrite_expr(expr, component, bound), span)
619	            }
620	            ActionItem::Ensures(expr, span) => {
621	                ActionItem::Ensures(rewrite_expr(expr, component, bound), span)
622	            }
623	            ActionItem::Let(name, expr, span) => {
624	                ActionItem::Let(name, rewrite_expr(expr, component, bound), span)
625	            }
626	            ActionItem::Statement(statement) => {
627	                ActionItem::Statement(rewrite_statement(statement, component, bound))
628	            }
629	        })
630	        .collect()
631	}
632	
633	fn rewrite_statements(
634	    statements: Vec<Statement>,
635	    component: &Component,
636	    bound: &HashSet<String>,
637	) -> Vec<Statement> {
638	    statements
639	        .into_iter()
640	        .map(|statement| rewrite_statement(statement, component, bound))
641	        .collect()
642	}
643	
644	fn rewrite_statement(
645	    statement: Statement,
646	    component: &Component,
647	    bound: &HashSet<String>,
648	) -> Statement {
649	    match statement {
650	        Statement::Assign {
651	            target,
652	            value,
653	            span,
654	        } => Statement::Assign {
655	            target: rewrite_lvalue(target, component, bound),
656	            value: rewrite_expr(value, component, bound),
657	            span,
658	        },
659	        Statement::If {
660	            condition,
661	            then_statements,
662	            else_statements,
663	            span,
664	        } => Statement::If {
665	            condition: rewrite_expr(condition, component, bound),
666	            then_statements: rewrite_statements(then_statements, component, bound),
667	            else_statements: rewrite_statements(else_statements, component, bound),
668	            span,
669	        },
670	        Statement::ForAll {
671	            binder,
672	            statements,
673	            span,
674	        } => {
675	            let binder = rewrite_binder(binder, component, bound);
676	            let mut nested = bound.clone();
677	            nested.insert(binder_name(&binder).to_owned());
678	            Statement::ForAll {
679	                binder,
680	                statements: rewrite_statements(statements, component, &nested),
681	                span,
682	            }
683	        }
684	    }
685	}
