844	fn rewrite_binder(binder: Binder, component: &Component, bound: &HashSet<String>) -> Binder {
845	    match binder {
846	        Binder::Typed {
847	            name,
848	            mut type_name,
849	            where_expr,
850	        } => {
851	            if type_name.namespace.is_none() && component.names.types.contains(&type_name.name) {
852	                type_name.name = prefix(&component.alias, &type_name.name);
853	            }
854	            let mut nested = bound.clone();
855	            nested.insert(name.clone());
856	            Binder::Typed {
857	                name,
858	                type_name,
859	                where_expr: where_expr
860	                    .map(|expr| Box::new(rewrite_expr(*expr, component, &nested))),
861	            }
862	        }
863	        Binder::Range {
864	            name,
865	            lo,
866	            hi,
867	            where_expr,
868	        } => {
869	            let mut nested = bound.clone();
870	            nested.insert(name.clone());
871	            Binder::Range {
872	                name,
873	                lo: Box::new(rewrite_expr(*lo, component, bound)),
874	                hi: Box::new(rewrite_expr(*hi, component, bound)),
875	                where_expr: where_expr
876	                    .map(|expr| Box::new(rewrite_expr(*expr, component, &nested))),
877	            }
878	        }
879	        Binder::Collection {
880	            name,
881	            collection,
882	            where_expr,
883	        } => {
884	            let mut nested = bound.clone();
885	            nested.insert(name.clone());
886	            Binder::Collection {
887	                name,
888	                collection: Box::new(rewrite_expr(*collection, component, bound)),
889	                where_expr: where_expr
890	                    .map(|expr| Box::new(rewrite_expr(*expr, component, &nested))),
891	            }
892	        }
893	    }
894	}
