1320	            first: Box::new(resolve_alias_expr(*first, components)?),
1321	            second: Box::new(resolve_alias_expr(*second, components)?),
1322	            third: Box::new(resolve_alias_expr(*third, components)?),
1323	        },
1324	        other => other,
