1329	    item: ActionItem,
1330	    components: &BTreeMap<String, Component>,
1331	) -> Result<ActionItem, CoreError> {
1332	    Ok(match item {
1333	        ActionItem::Requires(expr, span) => {
1334	            ActionItem::Requires(resolve_alias_expr(expr, components)?, span)
1335	        }
1336	        ActionItem::Ensures(expr, span) => {
1337	            ActionItem::Ensures(resolve_alias_expr(expr, components)?, span)
1338	        }
1339	        ActionItem::Let(name, expr, span) => {
1340	            ActionItem::Let(name, resolve_alias_expr(expr, components)?, span)
1341	        }
1342	        ActionItem::Statement(statement) => {
